INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 62, "2030/01/01 14:59:59", 1000001, 0.0, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", "2025/01/31 12:00:00", 1, "カリン", 1, 3.414, 190805, -416.5, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 62, "2030/01/01 14:59:59", 1000002, 0.0, "ミッションをクリアして、\n報酬をゲットしましょう！", "2025/01/31 12:00:00", 1, "カリン", 2, 3.099, 190805, -416.5, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 63, "2030/01/01 14:59:59", 1000003, 0.0, "受け取ることができる\n報酬があるようです\n確認してみてください", "2025/01/31 12:00:00", 1, "カリン", 3, 2.801, 190805, -416.5, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, 63, "2030/01/01 14:59:59", 1000004, 0.0, "報酬がもらえますよ！\nチェックしてみてください", "2025/01/31 12:00:00", 1, "カリン", 4, 0.0, 190805, -416.5, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, 64, "2030/01/01 14:59:59", 1000005, 0.0, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", "2025/01/31 12:00:00", 1, "カリン", 5, 2.12, 190805, -363.0, 1);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 64, "2030/01/01 14:59:59", 1000006, 0.0, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", "2025/01/31 12:00:00", 1, "カリン", 6, 1.68, 190805, -363.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, 64, "2030/01/01 14:59:59", 1000007, 0.0, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", "2025/01/31 12:00:00", 1, "カリン", 7, 2.33, 190805, -363.0, 1);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (3, 61, "2030/01/01 14:59:59", 1020101, -6.0, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", "2025/01/31 12:00:00", 10201, "ラビリスタ", 101, 5.18, 133701, -285.0, 7);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1020102, -2.0, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", "2025/01/31 12:00:00", 10201, "クリスティーナ", 201, 8.77, 133901, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (6, 61, "2030/01/01 14:59:59", 1020103, 0.0, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", "2025/01/31 12:00:00", 10201, "ネネカ", 301, 15.5, 133801, -285.0, 1);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, 61, "2030/01/01 14:59:59", 1020201, 0.0, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", "2025/02/28 12:00:00", 10202, "ランファ", 101, 9.061, 134301, -285.0, 5);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1020202, 0.0, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", "2025/02/28 12:00:00", 10202, "チカ", 201, 7.699, 134401, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1020301, 0.0, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", "2025/03/31 12:00:00", 10203, "アオイ", 101, 8.595, 134601, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1020302, 0.0, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", "2025/03/31 12:00:00", 10203, "クローチェ", 201, 7.758, 134501, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, 61, "2030/01/01 14:59:59", 1020401, 0.0, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", "2025/04/30 12:00:00", 10204, "ルイズマリー", 101, 7.0, 132302, -285.0, 6);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1020402, 0.0, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", "2025/04/30 12:00:00", 10204, "イロハ", 201, 7.904, 132402, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (4, 61, "2030/01/01 14:59:59", 1020403, 0.0, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", "2025/04/30 12:00:00", 10204, "ソノ", 301, 8.487, 132502, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1020502, 0.0, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", "2025/05/31 12:00:00", 10205, "カノン", 101, 8.763, 134901, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1020503, 0.0, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", "2025/05/31 12:00:00", 10205, "ツムギ", 201, 6.417, 134801, -285.0, 3);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (3, 61, "2030/01/01 14:59:59", 1020601, 0.0, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", "2025/06/30 12:00:00", 10206, "エリス", 101, 10.335, 135001, -285.0, 7);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, 61, "2030/01/01 14:59:59", 1020602, 0.0, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", "2025/06/30 12:00:00", 10206, "シェフィ", 201, 6.281, 135101, -285.0, 4);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1020603, 0.0, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", "2025/06/30 12:00:00", 10206, "プレシア", 301, 12.244, 135201, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, 61, "2030/01/01 14:59:59", 1020701, 0.0, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", "2025/07/31 12:00:00", 10207, "クリア", 101, 6.339, 135301, -285.0, 8);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (7, 61, "2030/01/01 14:59:59", 1020702, 0.0, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", "2025/07/31 12:00:00", 10207, "アネモネ", 201, 8.184, 135401, -285.0, 9);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (9, 61, "2030/01/01 14:59:59", 1020801, 0.0, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", "2025/08/31 12:00:00", 10208, "アイラ", 101, 3.906, 129101, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1020802, 0.0, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", "2025/08/31 12:00:00", 10208, "シナツ", 201, 14.465, 129201, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (4, 61, "2030/01/01 14:59:59", 1020803, 0.0, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", "2025/08/31 12:00:00", 10208, "ヒヨリ", 301, 8.662, 100101, -285.0, 3);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1020804, 0.0, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", "2025/08/31 12:00:00", 10208, "レイ", 401, 10.915, 100301, -285.0, 3);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1020901, 0.0, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", "2025/09/30 12:00:00", 10209, "ユキノ", 101, 6.042, 135802, -285.0, 7);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (4, 61, "2030/01/01 14:59:59", 1020902, 0.0, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", "2025/09/30 12:00:00", 10209, "サツキ", 201, 9.402, 135903, -285.0, 1);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (8, 61, "2030/01/01 14:59:59", 1020903, 0.0, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", "2025/09/30 12:00:00", 10209, "ルルィ", 301, 8.16, 136902, -285.0, 1);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (3, 61, "2030/01/01 14:59:59", 1021001, 0.0, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", "2025/10/31 12:00:00", 10210, "カスミ", 101, 5.0, 137401, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (4, 61, "2030/01/01 14:59:59", 1021002, 0.0, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", "2025/10/31 12:00:00", 10210, "アラクネ", 201, 8.12, 136001, -285.0, 1);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (4, 61, "2030/01/01 14:59:59", 1021003, 0.0, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", "2025/10/31 12:00:00", 10210, "ナーナ", 301, 6.386, 136202, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (3, 61, "2030/01/01 14:59:59", 1021101, 0.0, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", "2025/11/30 12:00:00", 10211, "ユイ", 101, 7.438, 136402, -285.0, 4);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1021102, 0.0, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", "2025/11/30 12:00:00", 10211, "ミソラ", 201, 8.35, 136302, -285.0, 5);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1021201, 0.0, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", "2025/12/31 12:00:00", 10212, "シズル", 101, 5.0, 136501, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1021202, 0.0, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", "2025/12/31 12:00:00", 10212, "リノ", 201, 5.25, 137902, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1021203, 0.0, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", "2025/12/31 12:00:00", 10212, "ラビリスタ", 301, 7.5, 106801, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1021301, 0.0, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", "2026/01/31 12:00:00", 10213, "ライラエル", 101, 8.204, 126501, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1021302, 0.0, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", "2026/01/31 12:00:00", 10213, "ネフィ＝ネラ", 201, 7.176, 129701, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1021303, 0.0, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", "2026/01/31 12:00:00", 10213, "ヴァイオレット", 301, 8.602, 133101, -285.0, 5);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1021304, 0.0, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", "2026/02/06 12:00:00", 10213, "ライラエル", 102, 10.14, 138101, -285.0, 3);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1021305, 0.0, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", "2026/02/06 12:00:00", 10213, "ネフィ＝ネラ", 202, 10.152, 138201, -285.0, 7);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (4, 61, "2030/01/01 14:59:59", 1021306, 0.0, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", "2026/02/06 12:00:00", 10213, "ヴァイオレット", 302, 9.688, 138001, -285.0, 3);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, 61, "2030/01/01 14:59:59", 1021307, 0.0, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", "2026/02/12 12:00:00", 10213, "ペコリーヌ", 401, 5.928, 138301, -285.0, 1);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (4, 61, "2030/01/01 14:59:59", 1021401, 0.0, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", "2026/02/28 12:00:00", 10214, "ワカナ", 101, 9.19, 138702, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1021402, 0.0, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", "2026/02/28 12:00:00", 10214, "シオリ", 201, 8.724, 138802, -285.0, 3);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (4, 61, "2030/01/01 14:59:59", 1021501, 0.0, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", "2026/03/31 12:00:00", 10215, "グレイス", 101, 7.758, 138902, -285.0, 1);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (6, 61, "2030/01/01 14:59:59", 1021502, 0.0, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", "2026/03/31 12:00:00", 10215, "キョウカ", 201, 6.375, 139002, -285.0, 4);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (6, 61, "2030/01/01 14:59:59", 1021503, 0.0, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", "2026/03/31 12:00:00", 10215, "ルルィ", 301, 6.173, 136902, -285.0, 1);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (6, 61, "2030/01/01 14:59:59", 1021601, 0.0, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", "2026/04/30 12:00:00", 10216, "ミホ", 101, 4.202, 139202, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (6, 61, "2030/01/01 14:59:59", 1021602, 0.0, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", "2026/04/30 12:00:00", 10216, "マホ", 201, 2.842, 139302, -285.0, 1);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (4, 61, "2030/01/01 14:59:59", 1021603, 0.0, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", "2026/04/30 12:00:00", 10216, "エリカ", 301, 4.598, 139402, -285.0, 1);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (4, 61, "2030/01/01 14:59:59", 1021701, 0.0, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", "2026/05/31 12:00:00", 10217, "リリ", 101, 6.533, 125802, -285.0, 3);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (3, 61, "2030/01/01 14:59:59", 1021702, 0.0, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", "2026/05/31 12:00:00", 10217, "プレシア", 301, 5.0, 126102, -285.0, 3);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (3, 61, "2030/01/01 14:59:59", 1021703, 0.0, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", "2026/05/31 12:00:00", 10217, "クリア", 201, 5.214, 126002, -285.0, 4);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1021704, 0.0, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", "2026/05/31 12:00:00", 10217, "リリ", 102, 8.781, 139501, -285.0, 3);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, 61, "2030/01/01 14:59:59", 1021705, 0.0, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", "2026/05/31 12:00:00", 10217, "クリア", 202, 6.529, 139601, -285.0, 1);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (3, 61, "2030/01/01 14:59:59", 1021706, 0.0, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", "2026/05/31 12:00:00", 10217, "プレシア", 302, 3.195, 139701, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, 61, "2030/01/01 14:59:59", 1021801, 0.0, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", "2026/06/30 12:00:00", 10218, "ルイズマリー", 101, 12.43, 139902, -285.0, 3);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, 61, "2030/01/01 14:59:59", 1021802, 0.0, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", "2026/06/30 12:00:00", 10218, "クレジッタ", 201, 6.35, 140001, -285.0, 3);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1021901, 0.0, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", "2026/07/31 12:00:00", 10219, "フブキ", 101, 10.23, 140102, -285.0, 5);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 61, "2030/01/01 14:59:59", 1021902, 0.0, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", "2026/07/31 12:00:00", 10219, "ヴァンピィ", 201, 5.584, 140201, -285.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 62, "2030/01/01 14:59:59", 2000001, 0.0, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", "2026/04/10 12:00:00", 2, "カリン", 1, 3.414, 190801, -416.5, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 62, "2030/01/01 14:59:59", 2000002, 0.0, "ミッションをクリアして、\n報酬をゲットしましょう！", "2026/04/10 12:00:00", 2, "カリン", 2, 3.099, 190801, -416.5, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 63, "2030/01/01 14:59:59", 2000003, 0.0, "受け取ることができる\n報酬があるようです\n確認してみてください", "2026/04/10 12:00:00", 2, "カリン", 3, 2.801, 190801, -416.5, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, 63, "2030/01/01 14:59:59", 2000004, 0.0, "報酬がもらえますよ！\nチェックしてみてください", "2026/04/10 12:00:00", 2, "カリン", 4, 0.0, 190801, -416.5, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, 64, "2030/01/01 14:59:59", 2000005, 0.0, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", "2026/04/10 12:00:00", 2, "カリン", 5, 2.12, 190801, -363.0, 1);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (1, 64, "2030/01/01 14:59:59", 2000006, 0.0, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", "2026/04/10 12:00:00", 2, "カリン", 6, 1.68, 190801, -363.0, 2);
INSERT INTO `v1_c109d0752bf6fae9ea04afabb5b619f404f9a2928c92622fbef308f2dafe45b3` VALUES (2, 64, "2030/01/01 14:59:59", 2000007, 0.0, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", "2026/04/10 12:00:00", 2, "カリン", 7, 2.33, 190801, -363.0, 1);
